  function availableStorage(kind) {
    try {
      const storage = kind === 'local' ? window.localStorage : window.sessionStorage;
      const probe = `${STORAGE_KEY}-probe`;
      storage.setItem(probe, '1');
      storage.removeItem(probe);
      return storage;
    } catch (_) {
      return null;
    }
  }

  const LOCAL_STORAGE = availableStorage('local');
  const SESSION_STORAGE = availableStorage('session');

  function clearStoredState() {
    for (const storage of [LOCAL_STORAGE, SESSION_STORAGE]) {
      try { storage?.removeItem(STORAGE_KEY); } catch (_) {}
    }
  }

  function loadState() {
    for (const storage of [LOCAL_STORAGE, SESSION_STORAGE]) {
      if (!storage) continue;
      try {
        const parsed = JSON.parse(storage.getItem(STORAGE_KEY) || 'null');
        if (parsed && parsed.answers) return { ...initialState(), ...parsed };
      } catch (_) {}
    }
    return initialState();
  }

  let state = loadState();
  state.aiPermissions = {...initialState().aiPermissions, ...(state.aiPermissions || {})};
  state.exportPermissions = {...initialState().exportPermissions, ...(state.exportPermissions || {})};
