function renderControl(q) {
  const type = q['Response Type'];
  const qid = q['Question ID'];
  if (q.Module === 'SCOPE') return renderScopeControl(q);
  if (qid === 'A02' || type === 'required_acknowledgment_checklist') return renderAcknowledgment(q);
  if (qid === 'A03' && !String(q['Options / Anchors']||'').includes('Categories =')) return renderSingle(q);
  if (qid === 'A04') return renderCanonicalPrivacyChoices(q);
  if (qid === 'A06' || type === 'goal_and_change_context') return renderCanonicalGoalContext(q);
  if (type === 'single_select') return renderSingle(q);
  if (type === 'acknowledgment_checklist') return renderAcknowledgment(q);
  if (type === 'sensitive_section_preference') return renderSensitivePreference(q);
  if (type === 'deployment_privacy_choices') return renderDeploymentPrivacy(q);
  if (type === 'research_use_consent') return renderSingle(q);
  if (type === 'goal_change_context') return renderGoalChange(q);
  if (type === 'checkbox_consent') return renderConsent(q);
  if (['multi_select','multi_select_searchable_grouped'].includes(type)) return renderMulti(q);
  if (type === 'multi_select_ordered') return renderOrderedMulti(q);
  if (['matrix_single_select','consent_topology_matrix','matrix_frequency','matrix_count_band','matrix_age_band','matrix_signed_influence'].includes(type)) return renderMatrixSingle(q);
  if (type === 'matrix_multi_select') return renderMatrixMulti(q);
  if (type === 'timeline_multi_select') return renderTimelineMulti(q);
  if (type === 'participant_naming') return renderParticipantNaming(q);
  if (type === 'repeatable_open_text') return renderRepeatable(q);
  if (['matrix_slider_0_100','matrix_bipolar_slider','matrix_bipolar_slider_0_100'].includes(type)) return renderMatrixSlider(q, /bipolar/.test(type));
  if (['matrix_slider_0_100_two_domain','matrix_slider_0_100_two_domain_dynamic'].includes(type)) return renderTwoDomainSlider(q);
  if (type === 'single_select_dynamic') return renderSingleDynamic(q);
  if (type === 'slider_0_100') return renderSlider(q);
  if (type === 'open_text') return renderOpen(q);
  if (type === 'three_part_open_text') return renderThreePartOpen(q);
  if (['role_pair_profile','role_pair_profile_extended'].includes(type)) return renderRolePairs(q);
  if (type === 'multi_select_dynamic') return renderMultiDynamic(q);
  if (type === 'matrix_likert_1_7') return renderMatrixLikert(q);
  if (type === 'matrix_change_profile') return renderMatrixChange(q);
  if (type === 'target_profile_setup') return renderTargetSetup(q);
  if (type === 'matrix_single_select_dynamic') return renderMatrixSingleDynamic(q);
  if (type === 'matrix_slider_0_100_dynamic') return renderMatrixSliderDynamic(q);
  if (type === 'matrix_frequency_two_domain') return renderTwoDomainSelect(q);
  if (type === 'matrix_change_profile_by_dyad') return renderDyadChange(q);
  if (type === 'likert_1_7') return renderLikert(q);
  if (type === 'rank') return renderRank(q);
  if (type === 'frequency_plus_slider') return renderFrequencyPlusSlider(q);
  if (type === 'optional_two_part_cue_profile') return renderCueProfile(q);
  if (type === 'optional_category_profile') return renderOptionalCategory(q);
  if (type === 'priority_matrix_plus_detail') return renderPriorityDetail(q);
  if (type === 'data_scope_permissions') return renderDataScope(q);
  if (type === 'dynamic_divergence_review') return renderDivergenceReview(q);
  if (type === 'section_feedback_matrix') return renderSectionFeedbackMatrix(q);
  if (type === 'correction_workflow') return renderCorrectionWorkflow(q);
  if (type === 'final_fit_and_disposition') return renderFinalDisposition(q);
  if (type === 'practice_status_matrix') return renderPracticeStatus(q);
  if (type === 'current_fit_and_disposition') return renderStructuredFallback(q);
  return renderStructuredFallback(q);
}


  function pathAttr(parts){return parts.map(x=>encodeURIComponent(String(x))).join('|');}
  function objectValue(id){const v=answer(id);return v&&typeof v==='object'&&!Array.isArray(v)?v:{};}
  function segmentOptions(q,key,nextKeys=[]){let s=scopeExtractSegment(q['Options / Anchors']||'',[key]);for(const n of nextKeys){const i=s.indexOf(`${n} =`);if(i>=0)s=s.slice(0,i);}return splitPipe(s).map(scopeStripPrefix);}
  function selectHTML(id,path,value,options,label='Not answered'){return `<select data-qid="${attr(id)}" data-path="${attr(pathAttr(path))}"><option value="">${esc(label)}</option>${options.map(o=>`<option value="${attr(o)}" ${value===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`;}
  function renderAcknowledgment(q){const id=q['Question ID'],v=Array.isArray(answer(id))?answer(id):[],opts=splitPipe(q['Options / Anchors']);return `<div class="ack-list">${opts.map(o=>`<label class="option ${v.includes(o)?'selected':''}"><input type="checkbox" data-qid="${attr(id)}" data-kind="multi" value="${attr(o)}" ${v.includes(o)?'checked':''}><span>${esc(o)}</span></label>`).join('')}</div><p class="help">All acknowledgments are required to continue.</p>`;}
  const PRIVACY_SESSION='Use responses only for this session and do not save them after I leave.';
  const PRIVACY_AI='Allow de-identified authorized fields to be sent to the named external AI service only when I request AI narrative generation';
  const PRIVACY_ASK='Ask me again before any external transmission';
  const PRIVACY_EXPORT='Allow me to export a copy';
  function supportedCanonicalPrivacyOptions(){
    const out=[PRIVACY_SESSION];
    if(state.aiEndpoint) out.push(PRIVACY_AI,PRIVACY_ASK);
    out.push(PRIVACY_EXPORT,'Do not begin the assessment');
    return out;
  }
  function renderCanonicalPrivacyChoices(q){
    const id=q['Question ID'],v=Array.isArray(answer(id))?answer(id):[],opts=supportedCanonicalPrivacyOptions();
    return `<div class="notice"><strong>Implemented in this build:</strong> session-only or no-save operation, manual export, and an optional user-configured AI endpoint. Persistent browser storage, account/cloud storage, and encrypted local storage are not offered.</div><div class="option-grid">${opts.map(o=>`<label class="option ${v.includes(o)?'selected':''}"><input type="checkbox" data-qid="${attr(id)}" data-kind="multi" value="${attr(o)}" ${v.includes(o)?'checked':''}><span>${esc(o)}</span></label>`).join('')}</div>`;
  }
  function renderCanonicalGoalContext(q){
    const id=q['Question ID'],v=objectValue(id),raw=String(q['Options / Anchors']||'');
    const marker='Part B current change =';
    const parts=raw.split(marker);
    const goalRaw=(parts[0]||'').replace(/^Part A goals, select all\s*=\s*/i,'');
    const goals=splitPipe(goalRaw), changes=splitPipe(parts[1]||'');
    const selected=Array.isArray(v.goals)?v.goals:[];
    return `<div class="compound-block"><h4>What you hope to understand</h4><div class="option-grid">${goals.map(o=>`<label class="option ${selected.includes(o)?'selected':''}"><input type="checkbox" data-qid="${attr(id)}" data-path="${attr(pathAttr(['goals']))}" data-path-kind="multi" value="${attr(o)}" ${selected.includes(o)?'checked':''}><span>${esc(o)}</span></label>`).join('')}</div><label><strong>How settled or changing your current experience feels</strong>${selectHTML(id,['currentChange'],v.currentChange,changes)}</label><p class="help">Assessment route is selected separately on the welcome screen and can be changed in Settings.</p></div>`;
  }

  function renderSensitivePreference(q){const id=q['Question ID'],v=objectValue(id),cats=segmentOptions(q,'Categories',['Options']),opts=segmentOptions(q,'Options');return `<div class="structured-grid">${cats.map(c=>`<label><strong>${esc(c)}</strong>${selectHTML(id,[c],v[c],opts)}</label>`).join('')}</div>`;}
  function renderDeploymentPrivacy(q){const id=q['Question ID'],v=objectValue(id);const rows=[['storage','Storage',['AI narrative','Exports']],['aiNarrative','AI narrative',['Exports']],['exports','Exports',[]]];return `<div class="structured-grid">${rows.map(([key,label,next])=>`<label><strong>${esc(label)}</strong>${selectHTML(id,[key],v[key],segmentOptions(q,label,next))}</label>`).join('')}</div>`;}
  function renderGoalChange(q){const id=q['Question ID'],v=objectValue(id),goals=Array.isArray(v.goals)?v.goals:[],changes=Array.isArray(v.changeAreas)?v.changeAreas:[],goalOpts=segmentOptions(q,'Goals',['Change areas','Route']),changeOpts=segmentOptions(q,'Change areas',['Route']),routeOpts=segmentOptions(q,'Route');return `<div class="compound-block"><h4>Goals</h4><div class="option-grid">${goalOpts.map(o=>`<label class="option ${goals.includes(o)?'selected':''}"><input type="checkbox" data-qid="${attr(id)}" data-path="${attr(pathAttr(['goals']))}" data-path-kind="multi" value="${attr(o)}" ${goals.includes(o)?'checked':''}><span>${esc(o)}</span></label>`).join('')}</div><h4>Areas currently changing</h4><div class="option-grid">${changeOpts.map(o=>`<label class="option ${changes.includes(o)?'selected':''}"><input type="checkbox" data-qid="${attr(id)}" data-path="${attr(pathAttr(['changeAreas']))}" data-path-kind="multi" value="${attr(o)}" ${changes.includes(o)?'checked':''}><span>${esc(o)}</span></label>`).join('')}</div><label><strong>Assessment route</strong>${selectHTML(id,['route'],v.route||state.route,routeOpts)}</label></div>`;}
  function renderCueProfile(q){const id=q['Question ID'],v=objectValue(id),cats=segmentOptions(q,'Categories',['For each']),dirs=['Increases','Decreases','Mixed','Context-dependent','Boundary-relevant','Not sure'];return `<div class="profile-list">${cats.map(c=>{const x=v[c]||{};const on=!!x.included;return `<article class="profile-row"><label class="option ${on?'selected':''}"><input type="checkbox" data-qid="${attr(id)}" data-path="${attr(pathAttr([c,'included']))}" data-path-kind="boolean" ${on?'checked':''}><span>${esc(c)}</span></label>${on?`<label>Relevance<input type="range" min="0" max="100" data-qid="${attr(id)}" data-path="${attr(pathAttr([c,'relevance']))}" data-path-kind="number" value="${Number.isFinite(Number(x.relevance))?Number(x.relevance):50}"></label><label>Direction${selectHTML(id,[c,'direction'],x.direction,dirs)}</label>`:''}</article>`}).join('')}</div>`;}
  function renderOptionalCategory(q){const id=q['Question ID'],v=objectValue(id),cats=segmentOptions(q,'Categories',['For each']);const kink=id==='J14';const freq=['Rarely','Sometimes','Often','Very often'];const real=['Fantasy only','Possibly interested','Would like to try consensually','Have consensual experience','Not sure','Prefer not'];const exp=['No experience','Past experience','Current or recent experience','Prefer not'];const interest=['Important or desired','Interested or curious','Open under some conditions','Neutral','Not interested','Firm boundary','Not sure','Prefer not'];return `<div class="profile-list">${cats.map(c=>{const x=v[c]||{};const on=!!x.included;return `<article class="profile-row"><label class="option ${on?'selected':''}"><input type="checkbox" data-qid="${attr(id)}" data-path="${attr(pathAttr([c,'included']))}" data-path-kind="boolean" ${on?'checked':''}><span>${esc(c)}</span></label>${on?(kink?`<label>Experience${selectHTML(id,[c,'experience'],x.experience,exp)}</label><label>Interest or boundary${selectHTML(id,[c,'interestBoundary'],x.interestBoundary,interest)}</label>`:`<label>Frequency${selectHTML(id,[c,'frequency'],x.frequency,freq)}</label><label>Importance<input type="range" min="0" max="100" data-qid="${attr(id)}" data-path="${attr(pathAttr([c,'importance']))}" data-path-kind="number" value="${Number.isFinite(Number(x.importance))?Number(x.importance):50}"></label><label>Real-life interest${selectHTML(id,[c,'realLifeInterest'],x.realLifeInterest,real)}</label>`):''}</article>`}).join('')}</div>`;}
  function renderPriorityDetail(q){const id=q['Question ID'],v=objectValue(id),prior=v.priorities||{},rows=segmentOptions(q,'Rows',['Priority','Overall detail']),opts=segmentOptions(q,'Priority',['Overall detail']),details=segmentOptions(q,'Overall detail');return `<div class="structured-grid">${rows.map(r=>`<label><strong>${esc(r)}</strong>${selectHTML(id,['priorities',r],prior[r],opts)}</label>`).join('')}</div><label><strong>Overall detail</strong>${selectHTML(id,['overallDetail'],v.overallDetail,details)}</label>`;}
  function renderDataScope(q){const id=q['Question ID'],v=objectValue(id),cats=segmentOptions(q,'Categories',['Operations','Global']),ops=segmentOptions(q,'Operations',['Global']),globals=segmentOptions(q,'Global');return `<div class="matrix-wrap"><table class="matrix"><thead><tr><th>Category</th>${ops.map(o=>`<th>${esc(o)}</th>`).join('')}</tr></thead><tbody>${cats.map(c=>`<tr><td>${esc(c)}</td>${ops.map(o=>{const arr=v.categories?.[c]||[];return `<td class="radio-cell"><input aria-label="${attr(c)} — ${attr(o)}" type="checkbox" data-qid="${attr(id)}" data-path="${attr(pathAttr(['categories',c]))}" data-path-kind="multi" value="${attr(o)}" ${arr.includes(o)?'checked':''}></td>`}).join('')}</tr>`).join('')}</tbody></table></div><h4>Global controls</h4><div class="option-grid">${globals.map(o=>{const arr=v.globals||[];return `<label class="option ${arr.includes(o)?'selected':''}"><input type="checkbox" data-qid="${attr(id)}" data-path="${attr(pathAttr(['globals']))}" data-path-kind="multi" value="${attr(o)}" ${arr.includes(o)?'checked':''}><span>${esc(o)}</span></label>`}).join('')}</div>`;}
  function detectedDivergenceRows(){const rows=derivePatterns().map(p=>p.label);if(state.scopeEnabled)rows.push(...calculateScopeResults().patterns.map(p=>p.label));return [...new Set([...rows,'Add another difference'])];}
  function renderDivergenceReview(q){const id=q['Question ID'],v=objectValue(id),rows=detectedDivergenceRows(),opts=segmentOptions(q,'Options');return `<div class="profile-list">${rows.map(r=>{const x=v[r]||{};return `<article class="profile-row"><strong>${esc(r)}</strong>${selectHTML(id,[r,'status'],x.status,opts)}${x.status==='Explain in my own words'||r==='Add another difference'?`<textarea data-qid="${attr(id)}" data-path="${attr(pathAttr([r,'explanation']))}">${esc(x.explanation||'')}</textarea>`:''}</article>`}).join('')}</div>`;}
